// Copy the browser runtime from node_modules into web/vendor with bare imports
// rewritten to relative paths, so the page needs no import map or bundler.
import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { join, resolve } from "node:path";
import { createHash } from "node:crypto";

const root = resolve(import.meta.dirname, ".."),
  out = join(root, "web/vendor");
const modules: Record<string, string> = {
  preact: "preact/dist/preact.module.js",
  "preact/hooks": "preact/hooks/dist/hooks.module.js",
  "@preact/signals-core": "@preact/signals-core/dist/signals-core.module.js",
  "@preact/signals": "@preact/signals/dist/signals.module.js",
  htm: "htm/dist/htm.module.js",
};
const file = (name: string) => name.replace(/^@/, "").replaceAll("/", "-") + ".js";
mkdirSync(out, { recursive: true });
for (const [name, path] of Object.entries(modules)) {
  let source = readFileSync(join(root, "node_modules", path), "utf8");
  for (const dep of Object.keys(modules))
    source = source.replaceAll(`from"${dep}"`, `from"./${file(dep)}"`);
  source = source.replace(/\n?\/\/# sourceMappingURL=.*$/m, "");
  writeFileSync(join(out, file(name)), source);
  console.log(`${file(name)} <- ${path}`);
}

// Brand and UI glyphs as path data, so a view can draw one inline without a request per icon.
const svgPath = (path: string) => readFileSync(join(root, "node_modules", path), "utf8").match(/<path d="([^"]+)"/)![1];
const octicons = (await import("@primer/octicons")).default;
const octicon = (name: string) => ({ box: 16, d: octicons[name].heights[16].path.match(/d="([^"]+)"/)![1] });
const icons = {
  claude: { box: 24, d: svgPath("@lobehub/icons-static-svg/icons/claude.svg") },
  openai: { box: 24, d: svgPath("@lobehub/icons-static-svg/icons/openai.svg") },
  pullRequest: octicon("git-pull-request"),
  play: octicon("play"),
  plus: octicon("plus"),
  trash: octicon("trash"),
  filter: octicon("filter"),
  signOut: octicon("sign-out"),
  paintbrush: octicon("paintbrush"),
  sync: octicon("sync"),
  arrowRight: octicon("arrow-right"),
  zap: octicon("zap"),
  person: octicon("person"),
  alert: octicon("alert"),
  arrowUp: octicon("arrow-up"),
  arrowDown: octicon("arrow-down"),
  dash: octicon("dash"),
  circleSlash: octicon("circle-slash"),
  commentDiscussion: octicon("comment-discussion"),
  checklist: octicon("checklist"),
  check: octicon("check"),
  x: octicon("x"),
  // Difficulty as one, two or three rising bars.
  bars1: { box: 16, d: "M2 10h3v4H2z" },
  bars2: { box: 16, d: "M2 10h3v4H2zM6.5 6h3v8h-3z" },
  bars3: { box: 16, d: "M2 10h3v4H2zM6.5 6h3v8h-3zM11 2h3v12h-3z" },
};
const iconModule = `// Generated by scripts/vendor-web.ts. Do not edit.\nexport const ICONS = ${JSON.stringify(icons, null, 2)};\n`;
writeFileSync(join(out, "icons.js"), iconModule);
// Vendors are cached; a changed glyph set needs a new URL in the shared Icon component.
const iconVersion = createHash("sha256").update(iconModule).digest("hex").slice(0, 12), dataFile = join(root, "web/ui/data.js");
writeFileSync(dataFile, readFileSync(dataFile, "utf8").replace(/from "\.\.\/vendor\/icons\.js(?:\?v=[^"]*)?"/, `from "../vendor/icons.js?v=${iconVersion}"`));
console.log("icons.js <- @lobehub/icons-static-svg, @primer/octicons");
